/**
 * Cached fixtures for every round except the one in progress (public/data/
 * results.json, generated by scripts/build-gameweeks.mjs and refreshed
 * daily): finished rounds have final scores, future rounds have their
 * (not-yet-started) fixture list. Loading this from one static, same-origin
 * file is far faster than hitting ESPN live for every past or advance-picked
 * round on every load. Only the in-progress round is still fetched from ESPN.
 */
import type { Fixture } from './espn'

let cache: Map<number, Fixture[]> | null = null

export async function loadResults(): Promise<Map<number, Fixture[]>> {
  if (cache) return cache
  try {
    const res = await fetch(`${import.meta.env.BASE_URL}data/results.json?t=${Date.now()}`)
    if (!res.ok) return new Map()
    const data = await res.json()
    const m = new Map<number, Fixture[]>()
    for (const [round, fixtures] of Object.entries(data.rounds ?? {})) {
      m.set(Number(round), fixtures as Fixture[])
    }
    cache = m
    return m
  } catch {
    return new Map()
  }
}
